 @PostMapping("/cases/{id}/actions")@ResponseStatus(HttpStatus.CREATED)public ActionResponse createAction(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ActionInput i){var s=require(EvidenceWorkflowPermissionGuard.ACTION,PrimeHrAction.ADD,t);return service.createAction(agency(a),id,i,t,actor(a),s,c);}@PutMapping("/cases/{id}/actions/{actionId}")public ActionResponse updateAction(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String actionId,@Valid@RequestBody ActionUpdate i){var s=require(EvidenceWorkflowPermissionGuard.ACTION,PrimeHrAction.EDIT,t);return service.updateAction(agency(a),id,actionId,i,actor(a),s,c);}@PostMapping("/cases/{id}/actions/{actionId}/submit")public ActionResponse submitAction(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String actionId,@Valid@RequestBody ActionSubmit i){var s=require(EvidenceWorkflowPermissionGuard.ACTION,PrimeHrAction.SUBMIT,t);return service.submitAction(agency(a),id,actionId,i,actor(a),s,c);}@PostMapping("/cases/{id}/actions/{actionId}/{action:start|verify|return|cancel}")public ActionResponse transitionAction(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String actionId,@PathVariable String action,@Valid@RequestBody Transition i){var required="start".equals(action)?PrimeHrAction.EDIT:PrimeHrAction.APPROVE;var s=require(EvidenceWorkflowPermissionGuard.ACTION,required,t);return service.transitionAction(agency(a),id,actionId,i,action,actor(a),s,c);}
